mapper.select:
SELECT sw.sku_id AS skuId, sw.weight AS weight
FROM sku_weight sw
JOIN (
  SELECT sku_id, MAX(effective_date) AS effectiveDate
  FROM sku_weight
  WHERE sku_id IN #{id}
    AND effective_date <= #{date}
  GROUP BY sku_id
) latest ON latest.sku_id = sw.sku_id AND latest.effectiveDate = sw.effective_date
